    """Run the wrapper script with given arguments, returning the result."""
    env = {**os.environ, **(env_extra or {})}
    return subprocess.run(
        [sys.executable, str(WRAPPER_SCRIPT), *args],
        capture_output=True, text=True, env=env,
    )

